-- =============================================================================
-- IAM Menu Seeder — canonical menu tree (generated from active iam.menus)
-- Idempotent: UPSERT by code, wire module/level/parent_id, prune stale menus.
-- Run: npm run db:seed:iam-menus
-- =============================================================================

ON CONFLICT (code) DO UPDATE SET
  menu_name            = EXCLUDED.menu_name,
  route_path           = EXCLUDED.route_path,
  icon                 = EXCLUDED.icon,
  menu_type            = EXCLUDED.menu_type,
  order_number         = EXCLUDED.order_number,
  permission_context   = EXCLUDED.permission_context,
  is_active            = true,
  is_visible           = true,
  deleted_at           = NULL,
  updated_at           = now();

UPDATE iam.menus
SET module = split_part(code, '.', 1),
    level  = (length(code) - length(replace(code, '.', ''))) + 1
WHERE deleted_at IS NULL;

UPDATE iam.menus child
SET parent_id = parent.id
FROM iam.menus parent
WHERE child.code LIKE '%.%'
  AND parent.code = left(child.code, length(child.code) - position('.' in reverse(child.code)))
  AND child.deleted_at IS NULL
  AND parent.deleted_at IS NULL;

UPDATE iam.menus SET parent_id = NULL WHERE code NOT LIKE '%.%' AND deleted_at IS NULL;

-- Soft-delete menus yang tidak ada di canonical tree
UPDATE iam.menus
SET is_active = false, is_visible = false, deleted_at = now(), updated_at = now()
WHERE deleted_at IS NULL
  AND code NOT IN ('dashboard', 'ess', 'hris', 'items', 'pos', 'crm', 'crm.overview', 'hris.recruitment', 'items.raw-material', 'pos.operations', 'crm.members', 'hris.workforce', 'items.product', 'pos.catalog', 'crm.loyalty', 'hris.organization', 'pos.kitchen', 'hris.compensation', 'pos.loyalty', 'hris.performance', 'pos.reports', 'hris.insights', 'purchasing.reports', 'crm.loyalty.rewards', 'crm.members.list', 'crm.overview.dashboard', 'hris.compensation.payroll', 'hris.insights.analytics', 'hris.organization.sections', 'hris.performance.kpi-templates', 'hris.recruitment.candidates', 'hris.workforce.attendance', 'items.product.master', 'items.raw-material.master', 'pos.catalog.products', 'pos.kitchen.kds', 'pos.loyalty.topup', 'pos.operations.cashier', 'pos.reports.dashboard', 'purchasing.reports.stock-card', 'crm.loyalty.avatars', 'hris.compensation.salary', 'hris.insights.reports', 'hris.organization.org-chart', 'hris.performance.logbook', 'hris.recruitment.pipeline', 'hris.workforce.leaves', 'items.product.inventory', 'items.raw-material.inventory', 'pos.catalog.stock-alerts', 'pos.kitchen.print-queue', 'pos.operations.restaurant', 'pos.reports.profit', 'pos.reports.closing', 'purchasing.reports.inventory-valuation', 'hris.performance.logbook-list', 'hris.recruitment.talent-pool', 'hris.workforce.schedules', 'items.product.purchasing', 'items.raw-material.purchasing', 'pos.kitchen.printer-settings', 'pos.operations.orders', 'purchasing.reports.po-summary', 'hris.performance.review', 'hris.recruitment.job-portal', 'items.product.approval', 'items.raw-material.approval', 'pos.operations.reservation', 'purchasing.reports.po-detail', 'items.product.production', 'items.raw-material.production', 'purchasing.reports.supplier-performance', 'items.product.approval.pr', 'items.product.inventory.stock', 'items.product.master.units', 'items.product.production.bom', 'items.product.purchasing.vendor', 'items.raw-material.approval.pr', 'items.raw-material.inventory.stock', 'items.raw-material.master.units', 'items.raw-material.production.bom', 'items.raw-material.purchasing.suppliers', 'items.product.approval.po', 'items.product.inventory.opname', 'items.product.master.categories', 'items.product.production.hub', 'items.product.purchasing.price-list', 'items.raw-material.approval.po', 'items.raw-material.inventory.opname', 'items.raw-material.master.categories', 'items.raw-material.production.hub', 'items.raw-material.purchasing.price-list', 'items.product.inventory.adjustment', 'items.product.master.products', 'items.product.purchasing.pr', 'items.raw-material.inventory.adjustment', 'items.raw-material.purchasing.pr', 'items.product.inventory.transfer', 'items.product.purchasing.po', 'items.raw-material.inventory.transfer', 'items.raw-material.master.materials', 'items.raw-material.purchasing.po', 'items.product.purchasing.delivery', 'items.raw-material.purchasing.delivery', 'items.product.purchasing.grn', 'items.raw-material.purchasing.grn', 'items.product.purchasing.returns', 'items.raw-material.purchasing.returns', 'items.product.purchasing.invoice', 'items.raw-material.purchasing.invoice', 'hris.master', 'hris.kepegawaian', 'hris.kepegawaian.users', 'hris.kepegawaian.contracts', 'hris.master.departments', 'hris.master.positions', 'hris.master.employment-statuses', 'settings', 'settings.business', 'settings.integrations', 'settings.appearance', 'settings.menus', 'settings.roles', 'pos.operations.tables', 'hris.recruitment.psikotes', 'settings.users');
